function hover(e,t){e.setAttribute("src",t)}function unhover(e,t){e.setAttribute("src",t)}$(document).ready(function(){$("body").scrollspy({target:"#sidebar",offset:100});$("a[href*=#]:not([href=#])").click(function(){if(location.pathname.replace(/^\//,"")==this.pathname.replace(/^\//,"")||location.hostname==this.hostname){var e=$(this.hash);e=e.length?e:$("[name="+this.hash.slice(1)+"]");if(e.length){var t=-20;if(this.hash!=="#intro"){t=e.offset().top}$("html,body").animate({scrollTop:t},1e3);return false}}});if(document.documentElement.clientWidth<992){$(".social-image img").each(function(){this.onmouseover=null});$(".social-image img").each(function(){this.onmouseout=null});$("#facebook-logo").attr("src","./img/facebook.jpg");$("#indiegogo-logo").attr("src","./img/indiegogo.jpg")}})